/* Presentation copy; evidence and design examples remain explicitly distinct. */
const desktopFrames = [
 {src:'desktop-1.png',label:'① 打开入口',caption:'真实遍历 · a0001：点击添加入口后出现城市对话框。顶部是系统更新通知，不能登记为应用动作的效果。'},
 {src:'desktop-3.png',label:'② 查询参数',caption:'真实遍历 · a0003：输入 London 后出现不同国家的候选。中间的搜索框点击 a0002 在本页省略展示，未省略真实记录。'},
 {src:'desktop-4.png',label:'③ 选择对象',caption:'真实遍历 · a0004：选择 London — United Kingdom。选择对象与最终添加是两个实际动作。'},
 {src:'desktop-5.png',label:'④ 核对结果',caption:'真实遍历 · a0005：点击 Add 后返回世界时钟列表，London 已出现。'}
];
const shot=(src,caption,cls='')=>`<figure class="${cls}"><div class="frame"><div class="window-bar"><i></i><i></i><i></i><span>真实运行画面 · 点击放大</span></div><img src="assets/${src}" alt="${caption}" data-zoom></div><figcaption>${caption}</figcaption></figure>`;
const foot=t=>`<p class="footnote">${t}</p>`;
const tag=(t,type='')=>`<span class="pill ${type}">${t}</span>`;
const slides = [
{chapter:'研究问题',title:'从 GUI 遍历，到可验证轨迹',eyebrow:'REGROW / METHOD WALKTHROUGH',hero:true,
body:`<div class="hero"><div><h1>先认识应用，<br>再构造<em>有意义</em><br>的交互轨迹。</h1><p>以区块功能知识连接视觉探索、<br>目标驱动的任务生成与实时执行。</p><small>研究方法讨论 · 15 页 · 2026.10.07</small></div><div class="hero-figure"><div class="window-bar"><i></i><i></i><i></i><span>一次知识生长的过程</span></div><div class="diagram-label">FROM INTERFACE TO EXPERIENCE</div><div class="big">observe.<br>understand.<br>regrow.</div><div class="hero-chain"><span>看见界面</span>→<span>理解功能</span>→<span>完成目标</span></div></div></div>`,
note:'汇报主线：我们希望将黑盒 GUI 探索的结果，转化成能支撑任务构造与执行的功能知识。演示中的方法示意、当前实现与真实实验分别标注。网页动效仅用于讲解，不模拟新的 GUI 执行。依据：design/RESEARCH_GOAL.md；当前逐步模块 README。'},
{chapter:'研究问题',eyebrow:'01 / MOTIVATION',title:'我们需要知道的，不止“下一步点哪里”',subtitle:'构造高质量 GUI 数据，需要把界面操作连接到用户目的和可检查的结果。',
body:`<div class="steps"><div class="step"><div class="num">01</div><h3>界面会重复出现</h3><p>导航栏、工具栏可能跨页面复用。每张截图都从头理解，容易重复探索。</p></div><div class="step"><div class="num">02</div><h3>点击不等于功能</h3><p>“打开城市选择器”只是入口；“添加指定城市”还需要查询、选中和提交。</p></div><div class="step"><div class="num">03</div><h3>走通不等于成功</h3><p>输入已写入、坐标已命中，都不足以证明目标完成。必须检查实际结果。</p></div></div><div class="callout">研究问题：能否用<strong>可复用、带证据的功能知识</strong>，支撑更自然、可执行且可验证的任务与轨迹？</div>`,
note:'这里陈述研究动机和待检验假设，不作相对现有方法的优越性结论。论文需通过同预算探索、任务质量及下游表现对照提供证据。依据：研究目标第 1、4 节。'},
{chapter:'总体方法',eyebrow:'02 / THE METHOD',title:'三阶段，把探索经验变成数据',subtitle:'整体先发现能力；生成单个任务时，先确定有意义的目标。',
body:`<div class="flow"><div class="node"><span class="pill">阶段 A</span><b>视觉遍历</b><p>发现区块、控件与未知功能<br>执行必要探索，记录真实反馈</p></div><div class="arrow">→</div><div class="node"><span class="pill">中间产物</span><b>区块功能知识</b><p>功能、参数、条件、入口关系<br>连同来源与未确认范围冻结</p></div><div class="arrow">→</div><div class="node"><span class="pill">阶段 B</span><b>目标驱动生成</b><p>选择共同用户目的<br>组织前置、分支和后续操作</p></div><div class="arrow">→</div><div class="node"><span class="pill">阶段 C</span><b>实时轨迹采集</b><p>参考图、观察当前界面<br>执行并核验最终业务结果</p></div></div><div class="callout">探索端回答“应用能做什么”；采集端回答“这一次，目标真的完成了吗”。</div>${foot('方法全链示意。已有局部接线与实机小试，完整复杂任务数据构造仍待系统验证。')}`,
note:'采集独立消费冻结只读图，不反向修改遍历、源图或活动运行。能力摘要与来源摘要固定；图路线仅是建议。当前新增跨区块功能支持的下游消费尚未验收，不把最新总结自动视为整条方法链已通过。依据：visual_collection.md、stepwise/knowledge.md、20261007 Clock 报告。'},
{chapter:'视觉遍历',eyebrow:'03 / REPRESENTATION',title:'围绕 Region，组织功能与证据',subtitle:'Region 是具有相对独立交互用途的界面区块；同一区块可以承载多个功能。',
body:`<div class="split wide">${shot('desktop-3.png','历史真实帧复用 · 桌面 Clock a0003 后图。前景是城市对话框；背后可见的导航不因此成为当前可操作对象。')}<div class="rows"><div class="row"><b>区块</b><span>当前表面的用途与可交互范围</span></div><div class="row"><b>控件</b><span>当前外观、物理归属和点击区域</span></div><div class="row"><b>功能知识</b><span>完整用户目的、参数与适用条件</span></div><div class="row"><b>证据关联</b><span>来源任务、实际动作及前后观察</span></div></div></div>${foot('方法解释，不是对该历史帧重新运行分区。身份外观与点击区域分别维护；旧外观不证明当前可操作。')}`,
note:'截图为 20261006 桌面真实遍历 a0003，不是本轮新执行。当前方法以 Region/控件及真实动作关系组织知识；不要将历史 Page/State 内核合同混为同一实现。稳定身份与一次观察位置分开。依据：stepwise/identity.md、context.md、CURRENT_FRAMEWORK.md。'},
{chapter:'视觉遍历',eyebrow:'04 / EXPLORATION LOOP',title:'发现 → 执行 → 观察更新',subtitle:'按需循环推进：每一次动作都回到新观察，形成可追溯的记录。',
body:`<div class="cycle"><div><span class="index">1</span><b>发现与准备任务</b><p>当前截图 + 已有记录<br>识别前景、区块和控件<br>提出值得调查的未知点</p></div><div><span class="index">2</span><b>选择并执行动作</b><p>已有任务 + 当前可操作性<br>核对对象和必要前置<br>形成实际投递与回执</p></div><div><span class="index">3</span><b>观察并更新记录</b><p>真实动作 + 前后截图<br>登记结果与信息缺口<br>推进、暂挂或转向其他工作</p></div></div><div class="return">↶ 新观察、新任务和新知识，进入下一轮</div><div class="callout">这是三类职责，<strong>并非每轮固定三次模型调用</strong>。补观察、纠错、任务清点和功能整理按需发生。</div>`,
note:'当前主入口 run_task_step._run_step，由 traversal_scheduler 选择并续接工作；locator/task_proposer/action_proposer/action_executor/result_updater 分别承担职责。已投递未登记的动作优先结算，不能因登记失败重新点击。依据：当前逐步 README、execution.md、updates.md。'},
{chapter:'视觉遍历',eyebrow:'05 / WHAT TO EXPLORE',title:'为未知信息探索，而非把按钮点一遍',subtitle:'任务提出器关注三类信息需求，并记录各自应得到的产物。',
body:`<div class="cards"><div class="card"><div class="symbol">↗</div><h3>新入口的功能</h3><p>它打开什么交互表面？<br>能帮助用户做什么？</p><div class="bracket"><span>应登记</span><p>实际去向与功能语义</p></div></div><div class="card"><div class="symbol">≋</div><h3>参数与适用条件</h3><p>有哪些可配置项？<br>在什么条件下生效？</p><div class="bracket"><span>应登记</span><p>观察到的参数事实</p></div></div><div class="card"><div class="symbol">?</div><h3>不确定控件的用途</h3><p>操作后出现什么反馈？<br>没有变化还是尚不可确认？</p><div class="bracket"><span>应登记</span><p>真实反馈及未知范围</p></div></div></div><div class="callout">已知用途可记录；同类数据与参数组合不穷举。<strong>缺少执行历史本身，不是必须重做的理由。</strong></div>${foot('现行任务合同。新入口产物分支尚缺完整原生执行验收；参数与缺口登记已有有限验证。')}`,
note:'registration_kind 表示信息产物类别，task_type 表示推进方式。参数部分选项可构成观察，但任务明确未知尚未回答时保留 registration_gap。试探无可见变化是反馈，不等于用途已确定。没有专门目标时，帮助/关于等辅助说明只记录；实际功能设置仍探索。依据：stepwise/tasks.md，20261007 登记合同与验证边界。'},
{chapter:'视觉遍历',eyebrow:'06 / REAL WALKTHROUGH',title:'一个真实片段：发现“添加城市”',subtitle:'按下方四个节点，查看真实动作后的界面变化。',
body:`<div class="split wide"><div>${shot('desktop-1.png',desktopFrames[0].caption,'walkthrough')}<div class="screen-step">${desktopFrames.map((f,i)=>`<button data-frame="${i}" class="${i===0?'selected':''}" aria-pressed="${i===0}">${f.label}</button>`).join('')}</div></div><div><div class="fact"><div class="label">观察如何变成功能证据</div><p id="walkText">添加入口揭示城市对话框。此时只证明入口去向，还不能说“城市已添加”。</p></div><div class="rows"><div class="row"><b>过程</b><span>打开 → 聚焦 → 输入 → 选中 → 添加</span></div><div class="row"><b>结果</b><span>最终列表出现 London</span></div><div class="row"><b>边界</b><span>单个连续片段；不是全应用完成</span></div></div></div></div>${foot('真实桌面 Clock · 2026-10-06 · a0001–a0005，展示 4 张关键后图；运行冻结源码 5f9325f。')}`,
note:'该片段含 5 个真实动作，此页省略 a0002 聚焦搜索框的重复画面。首图系统通知是外部事件，不应登记为按钮效果。点击节点切换仅在网页中展示已有帧，不发出 GUI 操作。原件：to_astra/desktop_clock_100_20261006_01/ACTIONS.md 与对应 receipts/after.png。'},
{chapter:'视觉遍历',eyebrow:'07 / REUSE WITH BOUNDARIES',title:'复用经验，也保留推翻旧判断的能力',subtitle:'区块身份、控件行为和本次执行结果，需要分别判断。',
body:`<div class="split"><div class="graph"><div class="g-node dark">历史区块 A<small>已知用途与来源证据</small></div><div class="g-arrow">⇢</div><div class="g-node">当前区块 A′<small>重新确认可见与可操作</small></div><div class="g-node">共享候选<small>外观与上下文提供线索</small></div><div class="g-arrow">↓</div><div class="g-node">实际反馈<small>支持复用，或撤回关联</small></div></div><div class="rows"><div class="row"><b>减少重复</b><span>已确认共享的任务知识按来源引用；同控件同动作不因改名重开。</span></div><div class="row"><b>保留差异</b><span>相似“＋”可能有不同功能；行为证据冲突时分离或复核。</span></div><div class="row"><b>不借用结果</b><span>历史经验不代表当前业务已成功；当前位置仍按新截图核验。</span></div></div></div><div class="callout">目标：减少重复理解与探索。实际节省多少调用、会引入多少误共享，仍需对照实验。</div>`,
note:'图中 A/A′ 是关系示意，不是真实图节点。共享区块行为由 shared_controls 维护，任务知识由 shared_tasks 引用；本地动作不迁移。候选位置/像素匹配不直接证明语义身份。当前仍有虚报控件、历史身份和归属缺口，不能声称可靠去重或跨应用稳定。依据：stepwise/identity.md、tasks.md。'},
{chapter:'功能知识',eyebrow:'08 / FROM ACTIONS TO CAPABILITIES',title:'将探索结果，整理为完整的用户目的',subtitle:'区块有效探索结束后，总结自身用途、参数、条件与独立功能。',
body:`<div class="split"><div><div class="bracket"><span>探索过程</span><p>入口 → 搜索 → 选择城市 → 点击 Add</p></div><div class="bracket"><span>方法上归纳的原子操作</span><p><strong>添加选定城市为世界时钟</strong></p></div><div class="bracket"><span>“原子”指最小完整用户目的</span><p>可以包含多个控件步骤；导航入口本身不代替业务目的。</p></div></div><div class="fact"><div class="label">一项可供下游使用的功能，需要保留</div><ul><li>用户对象与预期结果</li><li>支持这一目的的本地探索任务</li><li>已观察到的参数与适用条件</li><li>必要时引用外区块参数证据</li><li>来源、失败与尚未确认的范围</li></ul></div></div><div class="callout">同一区块可以有零项、一项或多项功能；已有任务闭合，不代表所有未发现功能都已覆盖。</div>${foot('功能归纳已有有限保存帧与现场补录；目录粒度、归属和跨区块支持仍需逐项核对。')}`,
note:'示例归纳与 20261007 Clock r0003 当前登记方向一致，但此页不是对整份目录的质量认证。总结不等待全子树，也不递归复制相邻区块知识；显式采用支持变化会触发复核。r0007/r0008 仍有旧摘要缺口；下游跨区块 support_tasks 消费未验证。依据：stepwise/knowledge.md、region_atomic_resume_clock_20261007_01/REPORT.md。'},
{chapter:'任务生成',eyebrow:'09 / GOAL-FIRST SYNTHESIS',title:'先确定目标，再挑选必要功能',subtitle:'让多个操作服务同一个用户目的，避免将相邻按钮机械拼成任务。',
body:`<div class="flow"><div class="node"><span class="pill">1 · 目的</span><b>用户想得到什么？</b><p>如处理一封财务月报，并整理到待核对的位置。</p></div><div class="arrow">→</div><div class="node"><span class="pill">2 · 约束</span><b>什么必须先成立？</b><p>确定同一邮件对象；观察附件；目标标签已存在。</p></div><div class="arrow">→</div><div class="node"><span class="pill">3 · 组合</span><b>哪些能力不可少？</b><p>搜索、阅读、条件回复、标签、归档；去掉无关操作。</p></div><div class="arrow">→</div><div class="node"><span class="pill">4 · 表达</span><b>自然用户指令</b><p>保留目标与条件，执行细节由实时界面决定。</p></div></div><div class="callout">生成时保留来源图和摘要；不把推断的可行性，当作已经执行成功的事实。</div>${foot('目标驱动组合属于研究方法；普通生成入口已有单功能小试，复杂组合质量仍待系统验收。')}`,
note:'Gmail 是 design/REGION_TRAVERSAL_ALIGNMENT.md 第 7 节的简化设计示例。导航可以是必要准备，却通常不是用户的最终业务目标。过滤冲突、撤销、冗余和无共同目的的组合是研究目标，不能宣称已在大规模自动生成中证明有效。'},
{chapter:'任务生成',eyebrow:'10 / CONDITIONAL TASK',title:'复杂任务：同一目标，可以有不同路径',subtitle:'方法示例 · Gmail 月报处理；此例没有新的实机验收。',
body:`<div class="split"><div><span class="pill design">设计示意 · 非执行回放</span><div class="body-copy">找到财务发来的“六月报表”。有附件则确认收到；无附件则请求补发。回复后添加“报表待核对”标签，再归档。</div><div class="callout" style="margin-top:24px">前提：该标签已存在。<br>执行时必须观察附件条件，且全程操作同一封邮件。</div></div><div class="branch"><div class="common">定位目标邮件 → 观察是否有附件</div><div class="choice">有附件 ↓<br><strong>回复确认收到</strong><small>“已收到附件，谢谢。”</small></div><div class="choice alt">无附件 ↓<br><strong>回复请求补发</strong><small>“邮件中没有看到附件，请补发，谢谢。”</small></div><div class="common">↓<br>添加“报表待核对”标签 → 归档</div></div></div>${foot('验收需分别检查条件观察、选中分支的回复，以及标签和归档结果；打开相应界面不能替代它们。')}`,
note:'严格沿用研究对齐文档中的 if/else 例子，不额外加入创建标签任务。这里五个逻辑节点是附件条件、两种回复、标签和归档；每条实际路径只执行一条回复分支。没有 Gmail 实机图，因此只画逻辑示意，不制作虚构界面截图。'},
{chapter:'轨迹采集',eyebrow:'11 / EXECUTE IN THE PRESENT',title:'图提供路线，当前界面决定怎么执行',subtitle:'采集读取冻结图；每一步以新截图确认对象、位置和实际结果。',
body:`<div class="cycle"><div><span class="index">A</span><b>读图与选目标</b><p>读取功能、条件和历史关系<br>选择下一项业务子目标<br>当前已可用的入口可直接使用</p></div><div><span class="index">B</span><b>核对与执行</b><p>当前图定位目标控件<br>外观框与点击框分别核对<br>明确错位先纠正再投递</p></div><div><span class="index">C</span><b>观察与验收</b><p>保存实际动作与前后帧<br>判断子目标及最终结果<br>失败保留 partial，不伪装成功</p></div></div><div class="callout">允许跳过不必要的导航；仍必须满足业务前置、观察分支条件，并完成必要确认。</div>${foot('采集与遍历隔离：源图只读，匹配实现固定，输出独立保存。定位通过不等于操作成功。')}`,
note:'普通 run_visual_collection 入口加载逐步图并构造视觉 guard。没有或有歧义的视觉匹配不自动判坐标错误，可转当前图模型确认。当前单功能小试的两次定位都经模型确认，不是真实模板正匹配案例。普通 CLI 的 max-turns 不等于独立 HTTP/GUI 硬额度；小试由外层限制并记账。'},
{chapter:'轨迹采集',eyebrow:'12 / REAL COLLECTION',title:'真实采集：看到候选，才完成查询',subtitle:'Android Clock · 目标是查询 London 并查看候选，不选择、不添加城市。',
body:`<div class="phone-row">${[
['collection-0.png','① 起点','原运行起点，London 已存在。'],
['collection-1.png','② 点击“＋”后','真实搜索页；历史图指导入口。'],
['collection-2.png','③ 输入 London 后','文本写入，候选尚未加载完成。'],
['collection-3.png','④ 等待新观察','候选出现，满足本次查询目标。']
].map(([s,t,c])=>`<figure><img src="assets/${s}" alt="${t}：${c}" data-zoom><b>${t}</b><figcaption>${c}</figcaption></figure>`).join('')}</div><div class="callout"><strong>成功重跑：8 次 HTTP / 2 次实际 GUI 投递</strong>，另有 wait 取新图。首轮输入提议因缺点位被拒绝；修复后独立重跑，失败记录保留。</div>${foot('2026-10-02 历史真实帧复用。生成 + 失败轮 + 重跑合计 12 HTTP / 3 GUI；最终勾选是初始已有状态，不是本次新增。')}`,
note:'原件：framework_wiring_collection_20261002_01/calls/0005 image_0、0007 image_1、0009 image_1、0011 image_1。重跑记录 click/input/wait 三个语义步骤、两个实际 primitive。首轮 input_text 没有点位，未执行该输入，不存在其执行后图；页面四张均为后续独立重跑。失败与成功不能拼为一次连续执行。'},
{chapter:'验证与论文',eyebrow:'13 / EVIDENCE BOUNDARY',title:'已有证据，到哪里为止？',subtitle:'把“已运行”“已接通”和“已证明有效”分开汇报。',
body:`<table class="table"><thead><tr><th>范围</th><th>已观察 / 已验证</th><th>仍不能据此声称</th></tr></thead><tbody><tr><td>桌面连续遍历<br><span class="pill live">真实 GUI</span></td><td>10 月 6 日批次：99 次模型调用、35 个动作，均有回执与后图；形成 14 区块、96 控件记录。</td><td>全应用覆盖、整图语义正确、跨应用稳定。仍有 pending / blocked。</td></tr><tr><td>探索产物与总结<br><span class="pill">有限验证</span></td><td>10 月 7 日续批：参数、缺口与功能归属有保存帧和局部现场验证。</td><td>所有目录质量合格；新入口产物链完整验收；最新跨区块支持已打通采集。</td></tr><tr><td>生成 → 采集<br><span class="pill live">单功能小试</span></td><td>普通入口读取冻结图，生成并完成一次 London 查询；保留失败及成功重跑。</td><td>复杂条件任务、批量数据质量、训练收益或正式论文结论。</td></tr></tbody></table>${foot('三行来自不同批次，不合并为一个同版本端到端实验。数字是运行记录规模，不是功能覆盖率。')}`,
note:'20261006 冻结源码 5f9325f；20261007 是保留旧图的续批，含监督审查、保存帧及定点补录，不称无人监督完整探索。20261002 采集用各自冻结源与旧图，不能证明最新知识合同全部适配下游。证据报告均列入本次 ASSET_MANIFEST 与审阅包。'},
{chapter:'验证与论文',eyebrow:'14 / PAPER STORY',title:'论文主线：让探索知识支撑任务与轨迹',subtitle:'拟检验的贡献：区块功能表示、目标驱动组合、实时结果核验之间能否形成有效链条。',
body:`<div class="steps"><div class="step"><div class="num">Q1</div><h3>探索是否更有效？</h3><p>同预算比较功能发现、重复操作和图错误；消融经验复用。</p></div><div class="step"><div class="num">Q2</div><h3>任务是否更有价值？</h3><p>比较自然性、可执行性、无效组合率与条件任务质量。</p></div><div class="step"><div class="num">Q3</div><h3>轨迹是否带来收益？</h3><p>核验真实业务成功与数据质量，再评估训练后的基准表现。</p></div></div><div class="callout">与老师讨论：<strong>以“能力知识驱动的数据构造”为主贡献</strong>，将遍历作为证据基础；用控制变量与消融，检验每一环的作用。</div>${foot('实验问题与评价维度是汇报建议，尚无比较结果；不在本次演示中宣布新颖性、覆盖率或性能提升。')}`,
note:'本页将既有研究目标压缩为讨论问题，不更改项目研究计划、不声称完成 M1–M6。后续正式方案需明确数据拆分、同预算基线、人工语义审核标准和下游训练/评测。演示参考项目当前目标、Region 对齐与现行模块合同；原始实验证据和当前源码分开保留。'}
];
